<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $activity = $args['activity']; $activity_id = absint( $activity->id ); ?><article class="sd-activity-card" data-activity-id="<?php echo esc_attr( $activity_id ); ?>"><header class="sd-activity-header"><img src="<?php echo esc_url( sd_avatar( $activity->user_id, 48 ) ); ?>" alt="" width="48" height="48"><div><strong><?php echo esc_html( sd_social_activity_author( $activity ) ); ?></strong><time datetime="<?php echo esc_attr( gmdate( 'c', strtotime( $activity->date_recorded ) ) ); ?>"><?php echo esc_html( $activity->date_recorded ); ?></time></div></header><div class="sd-activity-content"><?php echo wp_kses_post( wpautop( $activity->content ) ); ?></div><?php get_template_part( 'template-parts/social/activity-actions', null, array( 'activity_id' => $activity_id, 'activity' => $activity, 'favorite' => sd_social_activity_favorite_state( $activity_id ) ) ); ?><?php if ( is_user_logged_in() ) { get_template_part( 'template-parts/social/activity-comments', null, array( 'activity_id' => $activity_id ) ); } ?></article>
<?php if ( is_user_logged_in() && function_exists( 'sd_core_create_report' ) ) { sd_report_button( 'activity', $activity_id ); } ?>
